 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    # Find monochrome 3x3 tiles; each tile emits a central horizontal and vertical ray.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))
    for r, c, color in blocks:
        for x in range(w):
            out[r][x] = color
        for y in range(h):
            out[y][c] = color
    # When rays from distinct tiles cross, leave the crossing cell empty.
    for r, _, color_h in blocks:
        for _, c, color_v in blocks:
            if color_h != color_v:
                out[r][c] = 0
    return out
